def _val(sig):
    """Read a signal, treating x/z as 0.

    Gate-level flip-flops start undefined and there is no initial block,
    so int(sig.value) can raise before reset has propagated.
    """
    return int(sig.value.binstr.lower().replace("x", "0").replace("z", "0"), 2)


def _pins(dut, img_bit=0, img_shift=0, go=0, hd_bit=0, hd_shift=0,
          feat_shift=0):
    dut.ui_in.value = ((img_bit & 1) | ((img_shift & 1) << 1) |
                       ((go & 1) << 2) | ((hd_bit & 1) << 3) |
                       ((hd_shift & 1) << 4) | ((feat_shift & 1) << 5))


async def reset(dut):
    dut.ena.value = 1
    dut.uio_in.value = 0
    _pins(dut)
    dut.rst_n.value = 0
    await ClockCycles(dut.clk, 5)
    dut.rst_n.value = 1
    await ClockCycles(dut.clk, 2)


async def load_head(dut):
    for b in HEAD_BITS:
        _pins(dut, hd_bit=int(b), hd_shift=1)
        await ClockCycles(dut.clk, 1)
    _pins(dut)
    await ClockCycles(dut.clk, 1)


async def classify(dut, img_bits):
    for b in img_bits:
        _pins(dut, img_bit=int(b), img_shift=1)
        await ClockCycles(dut.clk, 1)
    _pins(dut)
    await ClockCycles(dut.clk, 1)

    _pins(dut, go=1)
    await ClockCycles(dut.clk, 1)
    _pins(dut)

    scores = [None] * NCLASS
    for _ in range(CYCLES * 3):
        await RisingEdge(dut.clk)
        uio = _val(dut.uio_out)
        if uio & 1:
            idx = (uio >> 3) & 0x7
            raw = _val(dut.uo_out)
            scores[idx] = raw - 256 if raw > 127 else raw
        if (uio >> 1) & 1:
            break
    return scores


@cocotb.test()
async def test_inference(dut):
    """Every score must match the numpy model exactly."""
    cocotb.start_soon(Clock(dut.clk, 100, units="ns").start())
    await reset(dut)
    await load_head(dut)

    for n, (img, expect) in enumerate(VECTORS):
        got = await classify(dut, img)
        assert got == expect, f"image {n}: expected {expect}, got {got}"
    dut._log.info(f"{len(VECTORS)} images, all scores bit-exact")


@cocotb.test()
async def test_reload_head(dut):
    """Reloading the head must reproduce the same answers.

    This is the retargeting path: the frozen backbone never changes, only
    the head bits do.
    """
    cocotb.start_soon(Clock(dut.clk, 100, units="ns").start())
    await reset(dut)
    await load_head(dut)
    first = await classify(dut, VECTORS[0][0])

    await load_head(dut)
    second = await classify(dut, VECTORS[0][0])
    assert first == second, f"reload changed the result: {first} vs {second}"


async def read_features(dut, n):
    """Shift the feature vector out on uio_out[6], one bit per pulse.

    feat_bit is combinational off the index register, so let it settle
    before sampling -- reading straight after the edge catches the old
    value.
    """
    bits = []
    for _ in range(n):
        await Timer(1, "ns")
        bits.append((_val(dut.uio_out) >> 6) & 1)
        _pins(dut, feat_shift=1)
        await ClockCycles(dut.clk, 1)
        _pins(dut)
    return bits


@cocotb.test()
async def test_feature_readout(dut):
    """The 56 features must match the numpy model bit for bit.

    This is the extractor claim: the frozen half of the chip computes the
    same features in silicon that it does in software.
    """
    cocotb.start_soon(Clock(dut.clk, 100, units="ns").start())
    await reset(dut)
    await load_head(dut)

    for n, (img, _expect, feats) in enumerate(FEATURE_VECTORS):
        await classify(dut, img)
        got = await read_features(dut, len(feats))
        assert got == list(feats), (
            f"image {n}: features differ at "
            f"{[i for i, (a, b) in enumerate(zip(got, feats)) if a != b]}")
    dut._log.info(f"{len(FEATURE_VECTORS)} feature vectors bit-exact")


@cocotb.test()
async def test_features_independent_of_head(dut):
    """Reloading the head must not change the features.

    The frozen half is frozen. Only the 90 bytes move.
    """
    cocotb.start_soon(Clock(dut.clk, 100, units="ns").start())
    await reset(dut)
    await load_head(dut)
    img = FEATURE_VECTORS[0][0]
    await classify(dut, img)
    first = await read_features(dut, NFEAT)

    await load_head(dut)
    await classify(dut, img)
    second = await read_features(dut, NFEAT)
    assert first == second, "features changed after a head reload"


@cocotb.test()
async def test_reset_midway(dut):
    """Reset partway through a load must not leave the chip stuck."""
    cocotb.start_soon(Clock(dut.clk, 100, units="ns").start())
    await reset(dut)
    for b in HEAD_BITS[:100]:
        _pins(dut, hd_bit=int(b), hd_shift=1)
        await ClockCycles(dut.clk, 1)

    await reset(dut)
    await load_head(dut)
    got = await classify(dut, VECTORS[0][0])
    assert got == VECTORS[0][1], f"after reset: expected {VECTORS[0][1]}, got {got}"
